mapper.select:
select * FROM (
    select ROWNUM as rnum, A.* from (
        select * from dc_hospital


                AND (hp_name LIKE '%' || #{keyword} || '%'
                     OR hp_addr LIKE '%' || #{keyword} || '%')


        order by hp_no desc
    ) A
    WHERE ROWNUM <= #{endRow}
)
WHERE rnum >= #{startRow}
